/*Table structure for table `unit` */

DROP TABLE IF EXISTS `unit`;

CREATE TABLE `unit` (
  `unit_id` bigint(20) NOT NULL COMMENT '单元id',
  `community_id` bigint(20) DEFAULT NULL COMMENT '小区id',
  `building_id` bigint(20) DEFAULT NULL COMMENT '楼栋id',
  `unit_name` varchar(32) DEFAULT NULL COMMENT '单元名称',
  `unit_code` varchar(128) DEFAULT NULL COMMENT '单元编号',
  `unit_level` int(11) DEFAULT NULL COMMENT '层数',
  `unit_acreage` decimal(32,10) DEFAULT NULL COMMENT '建筑面积',
  `unit_have_elevator` varchar(32) DEFAULT NULL COMMENT '是否有电梯',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`unit_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='单元 ';

